// Des: Commands plan, approve, go, flow: attended flows from CLI
// Flo: plan items > one approval list > approve > go runs by itself, waits only for the owner > summary + exit code
// I/O: Ctx + words (caller) > saved flow, list text, run summary; exit 0 ok, 3 items need you, 4 parked/blocked/unsafe
// ===================================================================
const std = @import("std"); const ctxz = @import("ct-ctrl-ctxz.zig"); const appr = @import("ru-appr-list.zig"); const flo = @import("st-flow-data.zig"); const fq = @import("ru-flow-queu.zig"); const sess = @import("ru-sess-ctxz.zig"); const uuid = @import("ut-uuid-seve.zig"); const wl = @import("ru-watc-loop.zig");
fn newFlow(ctx: *ctxz.Ctx, sto: anytype, name: []const u8, items: []const []const u8) !i64 { const now = ctxz.nowMs(ctx); const id = uuid.uuidNew(ctx.iozz, now); return appr.planFlow(sto, ctx.allo, &id, name, items, now); }
pub fn planRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.rest.len == 0) return error.BadJob; var sto = try ctxz.openStor(ctx); defer sto.close(); const fl = try newFlow(ctx, &sto, "plan", ctx.args.rest); try ctxz.emit(ctx, try appr.render(&sto, ctx.allo, fl)); return 0; }
pub fn approveRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.rest.len == 0) return error.BadJob; var sto = try ctxz.openStor(ctx); defer sto.close(); const lat = (try flo.flowLatest(&sto, ctx.allo)) orelse return error.BadJob; const what = try std.mem.join(ctx.allo, ",", ctx.args.rest); const cnt = try appr.approve(&sto, ctx.allo, lat.id, what); try ctxz.emitf(ctx, "approved {d} item(s)\n", .{cnt}); try ctxz.emit(ctx, try appr.render(&sto, ctx.allo, lat.id)); return 0; }
fn exitOf(res: fq.Result) u8 { return switch (res.kind) { .done, .preview => if (res.unsure + res.fail + res.skip > 0) 3 else 0, .parked, .blocked, .unsafe => 4 }; }
fn execFlow(ctx: *ctxz.Ctx, sto: anytype, fl: i64) !u8 { var live = try ctxz.openLive(ctx, false); defer live.close(); var ses = sess.Sess.init(ctx.init.gpa, ctx.iozz, ctx.allo, ctx.cfg, sto, live.conn, ctx.args.mode); ses.job = "flow"; const res = try fq.run(&ses, fl, .{ .stat = ctx.stat, .real_toast = !ctx.args.mock }); for (res.lines) |ln| try ctxz.emitf(ctx, "{s}\n", .{ln}); try ctxz.emitf(ctx, "flow {s} · done {d} · needs you {d} · failed {d} · skipped {d}\n", .{ @tagName(res.kind), res.done, res.unsure, res.fail, res.skip }); if (ctx.args.mode == .dry or ctx.args.mode == .read) try ctxz.emit(ctx, "nothing was changed (add --live to act)\n"); return exitOf(res); }
pub fn goRun(ctx: *ctxz.Ctx) !u8 { var sto = try ctxz.openStor(ctx); defer sto.close(); const lat = (try flo.flowLatest(&sto, ctx.allo)) orelse return error.BadJob; if (std.mem.eql(u8, lat.state, "done")) { try ctxz.emit(ctx, "the latest flow is done; plan a new one with: za plan\n"); return 0; } return execFlow(ctx, &sto, lat.id); }
pub fn watchRun(ctx: *ctxz.Ctx) !u8 { var sto = try ctxz.openStor(ctx); defer sto.close(); var live = try ctxz.openLive(ctx, false); defer live.close(); var ses = sess.Sess.init(ctx.init.gpa, ctx.iozz, ctx.allo, ctx.cfg, &sto, live.conn, if (ctx.args.mode == .live or ctx.args.mode == .force) .live else .read); ses.job = "watch"; const res = try wl.run(&ses, ctx.cfg.watc_chek_maxz, ctx.cfg.watc_deadl_mins); try ctxz.emitf(ctx, "watch ended: {s} · checks {d} · new messages {d} · breaks {d}{s}{s}\n", .{ @tagName(res.why), res.checks, res.newm, res.breaks, if (res.note.len > 0) " · " else "", res.note }); return if (res.why == .blocked) 4 else 0; }
pub fn flowRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.rest.len == 0) return error.BadJob; const sub = ctx.args.rest[0]; if (std.mem.eql(u8, sub, "list")) { for (ctx.cfg.flow_list) |fl| try ctxz.emitf(ctx, "{s}: {d} item(s)\n", .{ fl.name, fl.items.len }); if (ctx.cfg.flow_list.len == 0) try ctxz.emit(ctx, "no routines in flow_list\n"); return 0; } if (!std.mem.eql(u8, sub, "run") or ctx.args.rest.len < 2) return error.BadJob; const name = ctx.args.rest[1]; for (ctx.cfg.flow_list) |fl| { if (!std.mem.eql(u8, fl.name, name)) continue; if (fl.acct.len > 0 and !std.mem.eql(u8, fl.acct, ctx.acct)) { try ctxz.emitf(ctx, "routine {s} is for account {s}: skipped for {s}\n", .{ name, fl.acct, ctx.acct }); return 0; } var sto = try ctxz.openStor(ctx); defer sto.close(); const id = try newFlow(ctx, &sto, name, fl.items); try ctxz.emit(ctx, try appr.render(&sto, ctx.allo, id)); return execFlow(ctx, &sto, id); } return error.BadJob; }
